-- ============================================================
-- Greenfield Public School
-- Student Attendance Management System
-- MySQL Workbench-compatible dump
-- 224 students  |  16 teachers  |  8 classes  |  77 280 attendance rows
-- ============================================================

-- MySQL Workbench settings
SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0;
SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;
SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

-- Create & select database
CREATE DATABASE IF NOT EXISTS `attendance_db`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE `attendance_db`;

-- ------------------------------------------------------------
-- Table: tbladmin
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tbladmin`;
CREATE TABLE `tbladmin` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `firstName` VARCHAR(50) NOT NULL,
  `lastName` VARCHAR(50) NOT NULL,
  `emailAddress` VARCHAR(100) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `uq_admin_email` (`emailAddress`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table: tblterm
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblterm`;
CREATE TABLE `tblterm` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `termName` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table: tblsessionterm
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblsessionterm`;
CREATE TABLE `tblsessionterm` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `sessionName` VARCHAR(50) NOT NULL,
  `termId` VARCHAR(50) NOT NULL,
  `isActive` VARCHAR(10) NOT NULL DEFAULT '0',
  `dateCreated` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table: tblclass
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblclass`;
CREATE TABLE `tblclass` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `className` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table: tblclassarms
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblclassarms`;
CREATE TABLE `tblclassarms` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `classId` VARCHAR(10) NOT NULL,
  `classArmName` VARCHAR(255) NOT NULL,
  `isAssigned` VARCHAR(10) NOT NULL DEFAULT '0',
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table: tblclassteacher
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblclassteacher`;
CREATE TABLE `tblclassteacher` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `firstName` VARCHAR(255) NOT NULL,
  `lastName` VARCHAR(255) NOT NULL,
  `emailAddress` VARCHAR(255) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `phoneNo` VARCHAR(50) NOT NULL,
  `classId` VARCHAR(10) NOT NULL,
  `classArmId` VARCHAR(10) NOT NULL,
  `dateCreated` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `uq_teacher_email` (`emailAddress`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table: tblstudents
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblstudents`;
CREATE TABLE `tblstudents` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `firstName` VARCHAR(255) NOT NULL,
  `lastName` VARCHAR(255) NOT NULL,
  `otherName` VARCHAR(255) NOT NULL DEFAULT '',
  `admissionNumber` VARCHAR(255) NOT NULL,
  `password` VARCHAR(255) NOT NULL DEFAULT '12345',
  `classId` VARCHAR(10) NOT NULL,
  `classArmId` VARCHAR(10) NOT NULL,
  `dateCreated` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `uq_student_admno` (`admissionNumber`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- ------------------------------------------------------------
-- Table: tblattendance
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `tblattendance`;
CREATE TABLE `tblattendance` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `admissionNo` VARCHAR(255) NOT NULL,
  `classId` VARCHAR(10) NOT NULL,
  `classArmId` VARCHAR(10) NOT NULL,
  `sessionTermId` VARCHAR(10) NOT NULL,
  `status` VARCHAR(10) NOT NULL DEFAULT '0',
  `dateTimeTaken` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_att_admno` (`admissionNo`),
  KEY `idx_att_date` (`dateTimeTaken`),
  KEY `idx_att_class` (`classId`, `classArmId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




































































































































































































































































































































































































-- Restore settings
SET SQL_MODE=@OLD_SQL_MODE;
SET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;
SET UNIQUE_CHECKS=@OLD_UNIQUE_CHECKS;

